package com.nelja.urqr.audit;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;import com.nelja.urqr.hotel.Hotel;import com.nelja.urqr.access.user.StaffUser;
@Entity @Table(name="audit_record",indexes=@Index(name="ix_audit_hotel_created",columnList="hotel_id,created_at"))
public class AuditRecord {
 @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(name="hotel_id",nullable=false) private UUID hotelId; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="hotel_id",referencedColumnName="id",insertable=false,updatable=false) private Hotel hotel; @Column(name="user_id") private UUID userId; @ManyToOne(fetch=FetchType.LAZY) @JoinColumns({@JoinColumn(name="hotel_id",referencedColumnName="hotel_id",insertable=false,updatable=false),@JoinColumn(name="user_id",referencedColumnName="id",insertable=false,updatable=false)}) private StaffUser user; @Column(nullable=false,length=80) private String action; @Column(nullable=false,length=80) private String entity; @Column(name="entity_id",length=80) private String entityId; @Column(name="old_value",length=2000) private String oldValue; @Column(name="new_value",length=2000) private String newValue; @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt;
 protected AuditRecord(){} public AuditRecord(UUID h,UUID u,String a,String e,String id,String oldV,String newV){hotelId=h;userId=u;action=a;entity=e;entityId=id;oldValue=oldV;newValue=newV;createdAt=Instant.now();}
 public UUID getId(){return id;} public UUID getHotelId(){return hotelId;} public UUID getUserId(){return userId;} public String getAction(){return action;} public String getEntity(){return entity;} public String getEntityId(){return entityId;} public String getOldValue(){return oldValue;} public String getNewValue(){return newValue;} public Instant getCreatedAt(){return createdAt;}
}
